import{_ as a}from"./chunks/3510_sync_control_mode_diagram.tNcLb1Xz.js";import{_ as p,o as n,a as l,b as o}from"./app.C41L12d5.js";const e="/ascendc.github.io/assets/inter_core_aic_all_sync.DB06PmkS.png",C="/ascendc.github.io/assets/single_core_aiv_all_sync.Dfc9mRbc.png",c="/ascendc.github.io/assets/single_core_aic_aiv_sync_aiv_setflag.CbMVzNaB.png",r="/ascendc.github.io/assets/single_ai_core_aic_single_aiv_sync.Db7nX9yK.png",F=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核间同步","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync"},{"text":"关键特性说明","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features.md","filePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features.md","outlineHeaders":[{"level":2,"title":"多AI Core中AIC或者AIV全核同步","slug":"多AI-Core中AIC或者AIV全核同步","link":"#多AI-Core中AIC或者AIV全核同步"},{"level":2,"title":"单AI Core中AIV全核同步","slug":"单AI-Core中AIV全核同步","link":"#单AI-Core中AIV全核同步"},{"level":2,"title":"单AI Core中AIC与AIV全核同步","slug":"单AI-Core中AIC与AIV全核同步","link":"#单AI-Core中AIC与AIV全核同步"},{"level":2,"title":"单AI Core中AIC与单个AIV同步","slug":"单AI-Core中AIC与单个AIV同步","link":"#单AI-Core中AIC与单个AIV同步"}],"lastUpdated":1788180487000}'),I={name:"api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features.md"};function t(A,s,i,g,d,_){return n(),l("div",null,[...s[0]||(s[0]=[o('<div><article class="markdown-body"><h1>关键特性说明<span id="ZH-CN_TOPIC_0000002586300741"></span></h1><p>如图1所示，本章节将配合时序图介绍CrossCoreSetFlag和CrossCoreWaitFlag配合使用时支持的四种同步控制模式各自实现的原理。</p><ul><li>模式0：AI Core核间的同步控制。对于AIC全核场景，同步所有的AIC核，直到所有的AIC核都执行到CrossCoreSetFlag时，CrossCoreWaitFlag后续的指令才会执行；对于AIV全核场景，同步所有的AIV核，直到所有的AIV核都执行到CrossCoreSetFlag时，CrossCoreWaitFlag后续的指令才会执行。</li><li>模式1：AI Core内部，AIV核之间的同步控制。如果两个AIV核都运行了CrossCoreSetFlag，CrossCoreWaitFlag后续的指令才会执行。</li><li>模式2：AI Core内部，AIC与AIV之间的同步控制。在AIC核执行CrossCoreSetFlag之后，两个AIV上CrossCoreWaitFlag后续的指令才会继续执行；两个AIV都执行CrossCoreSetFlag后，AIC上CrossCoreWaitFlag后续的指令才能执行。</li><li>模式4：AI Core内部，AIC与单个AIV之间的同步控制。AIV0与AIV1可单独触发AIC等待。</li></ul><p><strong>图1</strong> 同步控制模式示意图<span id="fig37581010773"></span><br><img src="'+a+`" alt title="同步控制模式示意图"></p><p>下述同步特性均以该场景配置为例：每个AI Core包含1个AIC和M个AIV，共启动N个AI Core，即存在N个AIC和M * N个AIV。</p><h2 id="多AI-Core中AIC或者AIV全核同步">多AI Core中AIC或者AIV全核同步<span id="ZH-CN_TOPIC_0000002586180795"></span><a class="header-anchor" href="#多AI-Core中AIC或者AIV全核同步">​</a></h2><p>多AI Core中AIC或者AIV全核同步需要配套使用模式0的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。该场景可细分为两类：</p><ul><li><p>N个AI Core中的N个AIC进行全核同步。</p><p>当N个AIC都执行完CrossCoreSetFlag时，每个AIC对应flagId的计数器增加1。若AIC该flagId的计数器为非0，被CrossCoreWaitFlag所阻塞的所有指令才会执行下去，该flagId的计数器减去1。</p><p>对于每个AIC，CrossCoreSetFlag和CrossCoreWaitFlag都必须配对使用。</p></li><li><p>N个AI Core中的M * N个AIV进行全核同步。</p><p>当M * N个AIV都执行完CrossCoreSetFlag时，每个AIV核对应flagId的计数器增加1。若AIV该flagId的计数器为非0，被CrossCoreWaitFlag所阻塞的所有指令才会执行下去，该flagId的计数器减去1。</p><p>对于每个AIV，CrossCoreSetFlag和CrossCoreWaitFlag都必须配对使用。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 每个核都应该有类似如下的成对调用CrossCoreSetFlag和CrossCoreWaitFlag</span>
<span class="c1">// modeId必须配置为0，flagId要一致；CrossCoreWaitFlag的pipe使用默认值</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_M</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">       </span><span class="c1">// 待前置PIPE_M流水任务完成后，通知调度模块</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">0</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">              </span><span class="c1">// 直到所有AIC都完成前置PIPE_M流水，调度模块更新flagId=0的计数器后，解除阻塞。</span>
</code></pre></div></li></ul><p>以图1为例，演示N=2时，2个AI Core中的2个AIC进行全核同步。</p><p>AIC 1中在执行CrossCoreWaitFlag后，此时AIC 1 flagId=0的计数器为0，后续所有指令全部被阻塞，需要等到2个AIC核均执行完CrossCoreSetFlag。</p><p>AIC 2的CrossCoreSetFlag执行完后，此时调度模块感知到2个AIC均已执行完CrossCoreSetFlag，因此所有AIC各自的flagId=0的计数器值增加为1。AIC 1和AIC 2检测到各自对应的flagId=0的计数器变为1，都解除阻塞，继续执行后续指令，并且将计数器值减去1。</p><p><strong>图1</strong> 模式0：多AI Core中AIC全核同步<span id="zh-cn_topic_0000002517901268_fig288716464319"></span><br><img src="`+e+`" alt title="多AI_Core中AIC全核同步"></p><h2 id="单AI-Core中AIV全核同步">单AI Core中AIV全核同步<span id="ZH-CN_TOPIC_0000002555621176"></span><a class="header-anchor" href="#单AI-Core中AIV全核同步">​</a></h2><p>该场景需要配套使用模式1的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。</p><p>1个AI Core中的M个AIV进行全核同步。当M个AIV全部都执行完CrossCoreSetFlag时，每个AIV对应flagId的计数器增加1。若AIV该flagId的计数器为非0，被CrossCoreWaitFlag所阻塞的所有指令才会执行下去，该flagId的计数器减去1。对于每个AIV，CrossCoreSetFlag和CrossCoreWaitFlag都必须配对使用。</p><div class="callout callout-caution"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M4.47.22A.749.749 0 0 1 5 0h6c.199 0 .389.079.53.22l4.25 4.25c.141.14.22.331.22.53v6a.749.749 0 0 1-.22.53l-4.25 4.25A.749.749 0 0 1 11 16H5a.749.749 0 0 1-.53-.22L.22 11.53A.749.749 0 0 1 0 11V5c0-.199.079-.389.22-.53Zm.84 1.28L1.5 5.31v5.38l3.81 3.81h5.38l3.81-3.81V5.31L10.69 1.5ZM8 4a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 8 4Zm0 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意</p><p>该模式中，不同AI Core的AIV核之间不会互相影响同步。</p></div><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 每个AIV都应该有类似如下的成对调用CrossCoreSetFlag和CrossCoreWaitFlag</span>
<span class="c1">// modeId必须配置为1，flagId要一致；CrossCoreWaitFlag的pipe使用默认值</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">       </span><span class="c1">// 待前置PIPE_MTE3流水任务完成后，通知调度模块</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">1</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">                  </span><span class="c1">// 直到该AI Core中的所有AIV都完成前置PIPE_MTE3流水，调度模块更新flagId=0的计数器后，解除阻塞。</span>
</code></pre></div><p>以图2为例，演示M=2时，1个AI Core中的2个AIV进行全核同步。</p><p>AIV 1-1中在执行CrossCoreWaitFlag后，此时AIV 1-1 flagId=0的计数器为0，后续所有指令全部被阻塞，需要等到2个AIV均执行完CrossCoreSetFlag。</p><p>AIV 1-2的CrossCoreSetFlag执行完后，此时调度模块感知到2个AIV均已执行完CrossCoreSetFlag，因此将AIV 1-1和AIV 1-2各自的flagId=0的计数器值增加为1。AIV 1-1和AIV 1-2检测到各自对应的flagId=0的计数器变为1，都解除阻塞，继续执行后续指令，并且将计数器值减去1。</p><p><strong>图2</strong> 模式1：单AI Core中AIV全核同步<span id="zh-cn_topic_0000002518061186_fig15383112914156"></span><br><img src="`+C+`" alt title="单AI_Core中AIV全核同步"></p><h2 id="单AI-Core中AIC与AIV全核同步">单AI Core中AIC与AIV全核同步<span id="ZH-CN_TOPIC_0000002555780808"></span><a class="header-anchor" href="#单AI-Core中AIC与AIV全核同步">​</a></h2><p>单AI Core中AIC与AIV全核同步需要配套使用模式2的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。该场景可细分为两类：</p><ul><li><p>1个AI Core中的AIC执行CrossCoreSetFlag，对应的M个AIV都执行CrossCoreWaitFlag。</p><p>当AIC执行完CrossCoreSetFlag时，M个AIV对应flagId的计数器增加1。若AIV该flagId的计数器为非0，则解除AIV的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计AIC 1次调用CrossCoreSetFlag，对应M个AIV各1次CrossCoreWaitFlag才算配对使用。</p></li><li><p>1个AI Core中的M个AIV都执行CrossCoreSetFlag，对应的AIC执行CrossCoreWaitFlag。</p><p>当M个AIV全都执行完CrossCoreSetFlag时，AIC对应flagId的计数器增加1。若AIC该flagId的计数器为非0，则解除AIC的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计M个AIV各1次CrossCoreSetFlag，对应AIC 1次调用CrossCoreWaitFlag才算配对使用。</p></li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// AIC和AIV都应该有类似如下的成对调用CrossCoreSetFlag和CrossCoreWaitFlag</span>
<span class="c1">// modeId必须配置为2，flagId要一致；CrossCoreWaitFlag的pipe使用默认值</span>
<span class="k">if</span><span class="w"> </span><span class="n">ASCEND_IS_AIV</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">       </span><span class="c1">// 待前置PIPE_MTE3流水任务完成后，通知调度模块。必须要所有AIV都执行。</span>
<span class="p">}</span>
<span class="k">if</span><span class="w"> </span><span class="n">ASCEND_IS_AIC</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">2</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">                 </span><span class="c1">// 直到该AI Core中的所有AIV都完成前置PIPE_MTE3流水，调度模块更新flagId=0的计数器后，AIC解除阻塞。</span>
<span class="p">}</span>
</code></pre></div><p>以图3为例，演示M=2时，1个AI Core中AIV与AIC进行同步（AIV发起CrossCoreSetFlag）。</p><p>AIC 1中在执行CrossCoreWaitFlag后，此时AIC 1 flagId=0的计数器为0，后续所有指令全部被阻塞，需要等到2个AIV均执行完CrossCoreSetFlag。</p><p>当AIV 1-2的CrossCoreSetFlag在Vector指令1执行完后，前置PIPE_V的指令全部完成，CrossCoreSetFlag执行完成，但是此时AIV 1-1未执行CrossCoreSetFlag。因此AIC 1 flagId=0的计数器还是为0，AIC的所有指令依然被阻塞。</p><p>当AIV 1-1的Vector指令1、2全部执行完毕后，前置PIPE_V的指令全部完成，CrossCoreSetFlag生效。此时调度模块感知到2个AIV均已执行完CrossCoreSetFlag，因此将AIC 1 flagId=0的计数器值增加为1。AIC 1检测到对应的flagId=0的计数器变为1，则AIC 1核解除阻塞，继续执行后续指令Matrix指令2，并且将计数器值减去1。</p><p><strong>图3</strong> 模式2：单AI Core中AIC与AIV全核同步（AIV进行CrossCoreSetFlag）<span id="zh-cn_topic_0000002549581037_fig164171141103813"></span><br><img src="`+c+`" alt title="单AI_Core中AIC与AIV全核同步（AIV进行CrossCoreSetFlag）"></p><h2 id="单AI-Core中AIC与单个AIV同步">单AI Core中AIC与单个AIV同步<span id="ZH-CN_TOPIC_0000002586300742"></span><a class="header-anchor" href="#单AI-Core中AIC与单个AIV同步">​</a></h2><p>单AI Core中AIC与单个AIV同步需要配套使用模式4的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。该场景可细分为两类：</p><ul><li><p>1个AI Core中的AIC执行CrossCoreSetFlag，对应的AIV执行CrossCoreWaitFlag。</p><p>当AIC执行完CrossCoreSetFlag时，AIV对应flagId的计数器增加1。若AIV该flagId的计数器为非0，则解除AIV的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计AIC 1次调用CrossCoreSetFlag，单个AIV完成一次CrossCoreWaitFlag才算配对使用。</p></li><li><p>1个AI Core中的1个AIV执行CrossCoreSetFlag，对应的AIC执行CrossCoreWaitFlag。</p><p>当AIV执行完CrossCoreSetFlag时，AIC对应flagId的计数器增加1。若AIC该flagId的计数器为非0，则解除AIC的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计单个AIV 1次CrossCoreSetFlag，对应AIC 1次调用CrossCoreWaitFlag才算配对使用。</p></li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// AIC和AIV都应该有类似如下的成对调用CrossCoreSetFlag和CrossCoreWaitFlag </span>
<span class="c1">// modeId必须配置为4，flagId要一致 </span>
<span class="k">if</span><span class="w"> </span><span class="n">ASCEND_IS_AIV</span><span class="w"> </span><span class="p">{</span><span class="w"> </span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span><span class="w"> </span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">   </span><span class="c1">// 待AIV0上前置PIPE_MTE3流水任务完成后，通知调度器。对于flagId，AIV0上的0-15对应AIC上的0-15。 </span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="p">{</span><span class="w"> </span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">   </span><span class="c1">// 待AIV1上前置PIPE_MTE3流水任务完成后，通知调度器。对于flagId，AIV1上的0-15对应AIC上的16-31。 </span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span>
<span class="p">}</span><span class="w"> </span>
<span class="k">if</span><span class="w"> </span><span class="n">ASCEND_IS_AIC</span><span class="w"> </span><span class="p">{</span><span class="w"> </span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_FIX</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">        </span><span class="c1">// 阻塞后续PIPE_FIX流水指令，直到该AI Core中的AIV0都完成前置PIPE_MTE3流水，调度器更新flagId=0的计数器后，AIC解除阻塞 </span>
<span class="w">    </span><span class="p">...</span><span class="w"> </span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_FIX</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">16</span><span class="p">);</span><span class="w">       </span><span class="c1">// 阻塞后续PIPE_FIX流水指令，直到该AI Core中的AIV1都完成前置PIPE_MTE3流水，调度器更新flagId=16的计数器后，AIC解除阻塞 </span>
<span class="w">    </span><span class="p">...</span><span class="w"> </span>
<span class="p">}</span>
</code></pre></div><p>以图4为例，演示M=2时，1个AI Core中AIV1与AIC进行同步（AIV1-2发起CrossCoreSetFlag）。</p><p>AIC 1中在执行CrossCoreWaitFlag后，此时AIC 1 flagId=0的计数器为0，后续所有指令全部被阻塞，需要等到1个AIV执行完CrossCoreSetFlag。</p><ul><li>AIV 1-1不需要执行CrossCoreSetFlag。</li><li>AIV 1-2的PIPE_MTE3指令全部执行完毕后，CrossCoreSetFlag生效。此时调度模块感知1个AIV已执行完CrossCoreSetFlag，因此将AIC 1 flagId=0的计数器值增加为1。AIC 1检测到对应的flagId=0的计数器变为1，则AIC 1核解除阻塞，继续执行后续PIPE_FIX的指令，并且将计数器值减去1。</li></ul><p><strong>图4</strong> 模式4：单AI Core中AIC与单个AIV同步（AIV进行CrossCoreSetFlag）<span id="zh-cn_topic_0000002549581037_fig164171141103814"></span><br><img src="`+r+'" alt title="单AI_Core中AIC与单个AIV同步（AIV进行CrossCoreSetFlag）"></p></article></div>',1)])])}const S=p(I,[["render",t]]);export{F as __pageData,S as default};
